Create a C++ class representing a 2-dimensional point, along with an addition operation for combining two points, ensuring proper encapsulation.
class Point {
    private:
        int x, y;
    public: 
        Point(int x, int y) : x{x}, y{y} {};

int getX() const {
            return x;
        }

        int getY() const {
            return y;
        }

        void setX(int x) {
            this->x = x;
        }

        void setY(int y) {
            this->y = y;
        }

        Point operator+(const Point& other) const {
            return Point(x + other.getX(), y + other.getY());
        }
};

int main() {
    Point p1(3, 4);
    Point p2(1, 2);

    Point p3 = p1 + p2;

    std::cout << "p1 = (" << p1.getX() << ", " << p1.getY() << ")" << std::endl;
    std::cout << "p2 = (" << p2.getX() << ", " << p2.getY() << ")" << std::endl;
    std::cout << "p3 = p1 + p2 = (" << p3.getX() << ", " << p3.getY() << ")" << std::endl;

    return 0;
}

Character arrays are essentially strings in the C programming language. A character array allows storing an array of characters to represent a string. Note that the length of a string (or a character array) includes the null character ('\0') which marks the end of the string.

Below is a solution for your problem in C:

```c
#include <stdio.h>
#include <string.h>

int main() {
    // Define the character arrays
    char x[] = "Hello";
    char y[] = "World!";

    // Get the lengths of the arrays
    int length_x = strlen(x);
    int length_y = strlen(y);

    // Print the array with the superior length
    if(length_x > length_y) {
        printf("The array with the superior length is x: %s\n", x);
    } else if(length_y > length_x) {
        printf("The array with the superior length is y: %s\n", y);
    } else {
        printf("Both arrays have the same length.\n");
    }

    return 0;
}
```
Here, the `strlen` function is used to get the length of the arrays which includes the null character at the end. The lengths are then compared, and the array with the superior length is printed. If the lengths are equal, a corresponding message is printed.

