def generate_insert_statements(table_name, data):
    columns = set().union(*(d.keys() for d in data))
    insert_statements = []

    for row in data:
        values = []
        for col in columns:
            value = row.get(col)
            if value is None:
                values.append('NULL')
            elif isinstance(value, str):
                values.append(f"'{value}'")
            else:
                values.append(str(value))

        insert_statements.append(
            f"INSERT INTO {table_name} ({', '.join(columns)}) VALUES ({', '.join(values)});"
        )

