import torch
from torch.utils.data import Dataset
import numpy as np

class SyntheticNoiseDataset(Dataset):
    def __init__(self, original_dataset, noise_type='gaussian'):
        self.original_dataset = original_dataset
        self.noise_type = noise_type

    def __len__(self):
        return len(self.original_dataset)

    def add_gaussian_noise(self, image):
        noise = torch.randn_like(image) * 0.1
        noisy_image = image + noise
        return noisy_image

    def add_salt_and_pepper_noise(self, image):
        noise = torch.rand_like(image)
        noisy_image = image.clone()
        noisy_image[noise < 0.05] = 0.0  # Salt noise
        noisy_image[noise > 0.95] = 1.0  # Pepper noise
        return noisy_image

    def __getitem__(self, index):
        image, label = self.original_dataset[index]
        if self.noise_type == 'gaussian':
            noisy_image = self.add_gaussian_noise(image)
        elif self.noise_type == 'salt_and_pepper':
            noisy_image = self.add_salt_and_pepper_noise(image)
        else:
            raise ValueError("Unsupported noise type. Supported types are 'gaussian' and 'salt_and_pepper'.")
        return noisy_image, label
```

In this solution, we define the SyntheticNoiseDataset class as a subclass of torch.utils.data.Dataset. The __init__ method initializes the dataset with the original MNIST dataset and the noise_type parameter. The __len__ method returns the length of the original dataset. The add_gaussian_noise and add_salt_and_pepper_noise methods add Gaussian and salt-and-pepper noise to the input images, respectively. The __getitem__ method retrieves a noisy image and its corresponding label based on the specified noise type. If the noise type is not supported, a ValueError is raised.

