class Game:
    def __init__(self):
        self.board = [' ' for _ in range(9)]
        self.current_winner = None
        self.current_player = 'X'

    def print_board(self):
        for row in [self.board[i*3:(i+1) * 3] for i in range(3)]:
            print('| ' + ' | '.join(row) + ' |')

    def play_game(self):
        self.print_board()
        while self.winner() == None:
            self.make_move()
            self.print_board()
            self.change_player()
        if self.winner() == ' ':
            print("It's a tie!")
        else:
            print(self.winner() + ' wins!')

    def change_player(self):
        self.current_player = 'O' if self.current_player == 'X' else 'X'

    def make_move(self):
        valid_square = False
        while not valid_square:
            position = input(self.current_player + '\'s turn. Choose a spot (1-9): ')
            try:
                position = int(position)
                if position in range(1,10) and self.board[position-1] == ' ':
                    valid_square = True
                    self.board[position-1] = self.current_player
                else:
                    print('Invalid spot. Try another.')
            except ValueError:
                print('Invalid input. Try again')

    def winner(self):
        winning_combinations = [
            [0, 1, 2], [3, 4, 5], [6, 7, 8],  # rows
            [0, 3, 6], [1, 4, 7], [2, 5, 8],  # columns
            [0, 4, 8], [2, 4, 6] # diagonals
        ]
        for combination in winning_combinations:
            if self.board[combination[0]] == self.board[combination[1]] == self.board[combination[2]] != ' ':
                self.current_winner = self.board[combination[0]]
                return self.current_winner
        if ' ' not in self.board:
            return ' '
        return None

if __name__ == '__main__':
    g = Game()
    g.play_game()
```
