use strict;
use warnings;
use List::Util qw(sum);

sub median {
    my (@list) = @_;

    # checking if list is empty
    return "List is empty" unless @list;

    # insertion sort
    for my $i (1..$#list) {
        my $j = $i;
        while ($j > 0 && $list[$j-1] > $list[$j]) {
            @list[$j-1,$j] = @list[$j,$j-1];
            $j--;
        }
    }

    # calculating the median
    if (@list % 2) {
        # if list length is odd
        return $list[@list / 2];
    } else {
        # if list length is even
        return sum(@list[@list/2-1..@list/2]) / 2;
