    int len = strlen(formatted_string);
    int suffix_length = len;

    while (suffix_length > 0) {
        int start = len - suffix_length;
        int end = len - 1;
        bool is_palindrome = true;

        for (int i = 0; i < (suffix_length / 2); i++) {
            if (formatted_string[start+i] != formatted_string[end - i]) {
                is_palindrome = false;
                break;
            }
        }

        if (is_palindrome) {
            break;
        }

        suffix_length--;
    }

    free(formatted_string);
    return len - suffix_length;
}

// Most common char
char most_common(char* string) {
    char* formatted_string = format_string(string);
    int len = strlen(formatted_string);
    int frequency[26] = {0}; // assume only lowercase alphabets

    for (int i = 0; i < len; i++) {
        frequency[formatted_string[i] - 'a']++;
    }

    int max_frequency = 0;
    char most_common_char = '\0';

    for (int i = 0; i < 26; i++) {
        if (frequency[i] > max_frequency) {
            max_frequency = frequency[i];
            most_common_char = 'a' + i;
        }
    }

    free(formatted_string);
    return most_common_char;
}
```

This C code assumes all characters are lower-case alphabets and does not work for non-ASCII characters or digit characters. It also uses dynamic memory allocation, so it's important to free the memory after usage to avoid memory leak. As per C standard, You should always use `unsigned char` type cast for character to use them with `ctype.h` library functions because they are undefined for negative values and `char` type in C can be signed or unsigned which depends on the compiler and platform.

