```python
def custom_base_arithmetics(n, m, base, operation):
    if n > m or base < 2 or base > 10:
        return -1

    def to_base(num, b):
        if num == 0:
            return '0'
        digits = []
        while num:
            digits.append(str(num % b))
            num //= b
        return ''.join(reversed(digits))

    result = 0
    operation = operation.lower()

    if operation == "sum":
        result = sum(range(n, m + 1))
    elif operation == "diff":
        result = sum(range(n, m + 1)) // 2
    elif operation == "product":
        result = 1
        for i in range(n, m + 1):
            result *= i
    elif operation == "average":
        result = sum(range(n, m + 1)) // (m - n + 1)
    else:
        return -1

    return format(int(to_base(result, base)), f"0{o}").replace(f"0{o}", f"0{o}o")
```

