```python
class Fluid:
    def __init__(self, xquantity, yquantity):
        self.xquantity = xquantity
        self.yquantity = yquantity

    def interpolate(self, target):
        for index in range(len(self.xquantity) - 1):
            if self.xquantity[index] <= target <= self.xquantity[index + 1]:
                return self.yquantity[index] + \
                    (self.yquantity[index + 1] - self.yquantity[index]) * \
                    (target - self.xquantity[index]) / (self.xquantity[index + 1] - self.xquantity[index])
```

