    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/upload', methods=['GET', 'POST'])
def upload_file():
    if request.method == 'POST':
        if 'file' not in request.files:
            return render_template('file/upload.html', error='No file part')
        file = request.files['file']
        if file.filename == '':
            return render_template('file/upload.html', error='No selected file')
        if file and allowed_file(file.filename):
            filename = secure_filename(file.filename)
            file.save(os.path.join(app.config['UPLOAD_FOLDER'], filename))
            return redirect(url_for('success', filename=filename))
        else:
            return render_template('file/upload.html', error='Invalid file type')

    return render_template('file/upload.html')

@app.route('/success/<filename>')
def success(filename):
    return render_template('file/success.html', filename=filename)

if __name__ == '__main__':
    app.run(debug=True)
