#[derive(Clone)]
struct Token {
    token: Option<String>,
}

enum Keywords {
    TRUE,
}

impl Token {
    fn new_empty() -> Self {
        Token { token: None }
    }

    fn expect_keyword(&self, keyword: &Keywords) -> bool {
        match keyword {
            Keywords::TRUE => self.token.as_deref() == Some("true"),
        }
    }
}

struct TokenValue {
    token: Token,
    value: bool,
}

impl TokenValue {
    fn new() -> Self {
        TokenValue {
            token: Token::new_empty(),
            value: false,
        }
    }

    fn from_token(token: Token) -> Self {
        Self {
            token: token.clone(),
            value: token.expect_keyword(&Keywords::TRUE),
        }
    }

    // Add the to_string method here
}
```

