def string_xor(a: str, b: str) -> str:

    # First we check if the strings are not exceeding length 10^3, and if they do, we raise an exception
    if len(a) > 10**3 or len(b) > 10**3:
        raise ValueError("Input strings length should not exceed 10^3 characters.") 

    # Then we check if the strings are comprised only of 1s and 0s. If not, we raise an exception
    if not set(a).issubset(set('01')) or not set(b).issubset(set('01')):
        raise ValueError("Input should only contain binary digits (i.e., 1s and 0s).")

    # If the strings are of different lengths, we pad the shorter one with 0s at the beginning
    if len(a) != len(b):
        if len(a) < len(b):
            a = a.zfill(len(b))
        else:
            b = b.zfill(len(a))

    # Then we conduct the XOR operation
    result = ''
    for i in range(len(a)):
        # XOR operation
        if a[i] == b[i]:
            result += '0'
        else:
