        self.original_dict = dictionary.copy()
        self.modified_dict = {}

    def __getitem__(self, key):
        return self.original_dict.get(key, self.modified_dict.get(key))

    def __setitem__(self, key, value):
        if key in self.original_dict and key not in self.modified_dict:
            self.modified_dict[key] = self.original_dict[key]
        self.modified_dict[key] = value

