In JavaScript, you can create a deep copy of an object using the JSON.parse and JSON.stringify methods. However, this method will not handle circular references. To handle circular references, you'll have to create a custom function, using "WeakMap" to keep track of circular references. Here is an example:

```javascript
function deepClone(obj, hash = new WeakMap()) {
    if (hash.has(obj)) return hash.get(obj); // If circular reference is detected
    if (obj instanceof RegExp) return new RegExp(obj);
    if (obj instanceof Date) return new Date(obj);
    if (obj === null || typeof obj !== 'object') return obj;
    let clone = Array.isArray(obj) ? [] : {};
    hash.set(obj, clone);
    for (let key in obj) {
        if (obj.hasOwnProperty(key)) { 
            clone[key] = deepClone(obj[key], hash); 
        }
    }
    return clone;

}
