            self.seg_tree[node] = self.arr[start]
            return 
        mid = (start + end) // 2
        self.build_tree(2*node+1, start, mid)
        self.build_tree(2*node+2, mid+1, end)
        self.seg_tree[node] = self.seg_tree[2*node+1] * self.seg_tree[2*node+2]

