Go doesn't directly support regular expressions or translation of numbers into words through built-in functions like Python. However, there are libraries that provide these features. Here is how you can apply most of this logic in Go using the 'regexp' and 'icza/gox' libraries. However, number to words conversion isn't handled here as it isn't directly supported as a library in Go.

Install the 'gox' library:
```
go get github.com/icza/gox
```

Here is your Python code converted to Go:

```go
package main

import (
	"fmt"
	"github.com/icza/gox"
	"regexp"
	"strings"
)

func complex_string_transformations(text string) string {
	// Building a list of words for proper handling spaces
	words := strings.Fields(text)

	var processedWords []string
	for _, word := range words {
		// Strip the punctuation using RegEx
		reg, _ := regexp.Compile("[^a-zA-Z0-9]+")
		cleanWord := reg.ReplaceAllString(word, "")

		// Go does not have a direct equivalent of Python's `num2words` package
		// That functionality is not implemented in this snippet

		// Invert the sequence of the characters using gox library
		revRune := gox.RevRuneSlice([]rune(cleanWord))
		cleanWord =  string(revRune)

		// Capitalize the word
		cleanWord = strings.Title(cleanWord)

		processedWords = append(processedWords, cleanWord)
	}

	// Combine words back into a string with _ instead of spaces
	result := strings.Join(processedWords, "_")

	// Replace 2 or more consecutive _ with a -
	reg, _ := regexp.Compile("_{2,}")
	result = reg.ReplaceAllString(result, "-")
	return result
}

func main() {
	fmt.Println(complex_string_transformations("your string here"))
}
```

