```javascript
// This is a JavaScript function that will check if a number is prime
function isPrime(n) {
    // If n is less than 2, it's not a prime number, so, we return false
    if (n < 2) {
        return false;
    }

    // Check divisibility from 2 up to the square root of n
    // Based on the mathematical fact that a factor of n 
    // must be less than the square root of n
    for (let i = 2; i <= Math.sqrt(n); i++) {
        // If n is divisible by any number within this range, then it's not a prime number
        if (n % i == 0) {
            return false; // so, we return false
        }
    }

    // If we reach this point, then n can only be divisible by 1 and itself, 
    // so it's a prime number
    return true;
}
