        get = "/identifiers"
        response = self._do_request(get)
        if not response:
            logging.error("Unable to connect to Metax API")
            return None

        try:
            response.raise_for_status()
            return self.json_or_empty(response)
        except requests.HTTPError as e:
            logging.error(f'Failed to get identifiers from Metax: \nerror={e}, \njson={self.json_or_empty(response)}')
