class ResolutionManager:
    def __init__(self, easy_client=None):
        self.easy_client = easy_client
        self.resolver_map = []

    def build_resolver_map(self):
        """Builds the resolver map using the build_resolver_map function"""
        self.resolver_map = build_resolver_map(self.easy_client)

    def resolve_data(self, data):
        """Iterates through the resolver map and uses the appropriate resolver to process the incoming data"""
        for resolver in self.resolver_map:
            if resolver.can_handle(data):
                resolver.resolve(data)
                break  # Stop after the first resolver handles the data

class IdentityResolver:
    def can_handle(self, data):
        """Checks if the resolver can handle the data"""
        return True  # IdentityResolver can handle any type of data

    def resolve(self, data):
        """Processes the data using the identity resolution strategy"""
        print("IdentityResolver: Processing data -", data)

class BytesResolver:
    def __init__(self, easy_client):
        self.easy_client = easy_client

    def can_handle(self, data):
        """Checks if the resolver can handle the data"""
        return isinstance(data, bytes)

    def resolve(self, data):
        """Processes the bytes data using the BytesResolver strategy"""
        print("BytesResolver: Processing bytes data -", data)

class ChunksResolver:
    def __init__(self, easy_client):
        self.easy_client = easy_client

    def can_handle(self, data):
        """Checks if the resolver can handle the data"""
        return isinstance(data, list) and all(isinstance(chunk, bytes) for chunk in data)

    def resolve(self, data):
        """Processes the list of byte chunks using the ChunksResolver strategy"""
        print("ChunksResolver: Processing byte chunks -", data)

