Here's a simple C++ solution for computing factorial using recursion with functionality that handles invalid inputs:

```cpp
#include <iostream>
#include <limits>

// Function to compute factorial recursively
long double factorial(long long n){
    // Base case
    if(n == 0){
        return 1;
    }
    else if (n < 0){
        // Return -1 as error code for negative input
        return -1;
    }
    else if (n > 170){
        // Return -2 as error code for input that is too large
        return -2;
    }
    else {
        // Recursive case
        return n * factorial(n-1);
    }
}

int main(){
    long long num;
    std::cout << "Enter a positive integer: ";
    std::cin >> num;

    // Check for valid integer input
    if(std::cin.fail()){
        std::cout << "Not a valid integer input." << std::endl;
        return 1;
    }

    long double result = factorial(num);

    // Check for error codes
    if(result == -1){
        std::cout << "Factorial is not defined for negative numbers." << std::endl;
        return 1;
    }
    else if(result == -2){
        std::cout << "Factorial computation for this number exceeds system limit." << std::endl;
        return 1;
    }
    else{
        std::cout << "Factorial of " << num << " is: " << result << std::endl; 
    }
    return 0;
}
```

Please note that integer values over 170 are out of the floating point range in most modern compilers, so the above program treats this as an error. The `std::cin.fail()` method is used to check for invalid integer input from the user. The user will therefore be informed if their input is either not an integer, negative, or too large.

