```kotlin
fun parseNestedStructure(strings: List<String>): Any? {
    val nestedStructure = mutableMapOf<String, Any?>()
    var currentMap = nestedStructure

    for (line in strings) {
        val depth = line.takeWhile { it.isWhitespace() }.length / 2
        val key = line.trim()

        if (depth == 0) {
            currentMap[key] = mutableMapOf<String, Any?>()
            currentMap = currentMap[key] as MutableMap<String, Any?>
        } else {
            var tempMap = nestedStructure
            repeat(depth) {
                tempMap = tempMap.values.last() as MutableMap<String, Any?>
            }
            tempMap[key] = mutableMapOf<String, Any?>()
            currentMap = tempMap[key] as MutableMap<String, Any?>
        }
    }

    return nestedStructure["root"]
}
```

