    }

    public static int lcm(int num1, int num2) {
        if (num1 == 0 || num2 == 0) {
            return 0;
        }
        int absNum1 = Math.abs(num1);
        int absNum2 = Math.abs(num2);
        int max = Math.max(absNum1, absNum2);
        int min = Math.min(absNum1, absNum2);
        for (int i = max;; i += max) {
            if (i % min == 0) {
                return i;
            }
        }
    }
}
```

