function gcdPrimeFactors(arr) {
    const primeFactors = num => {
        const factors = [];
        for(let div = 2; num !== 1; div++) {
            while(num % div === 0) {
                factors.push(div);
                num /= div;
            }
        }
        return factors;
    }
    let minNumIndex = arr.indexOf(Math.min(...arr));
    let smallestPrimeFactors = primeFactors(arr[minNumIndex]);
    for(let i = 0; i < arr.length; i++){
        if(i !== minNumIndex){
            let currentNumPrimeFactors = primeFactors(arr[i]);
            smallestPrimeFactors = smallestPrimeFactors.filter(val => {
                let index = currentNumPrimeFactors.indexOf(val);
                if(index !== -1){
                    currentNumPrimeFactors.splice(index, 1);
                    return true;
                }
                return false;
            });
        }
    }
    return smallestPrimeFactors.reduce((a, b) => a * b, 1);
}
