my $input = <STDIN>;
chomp $input;

# Check if the input is a valid integer
if ($input =~ /^[+-]?\d+$/) {
    # Convert the input to a positive integer
    my $n = abs($input);

    # Check if n is zero
    if ($n == 0) {
        print "Error: Input cannot be zero\n";
    }
    # Check if n is too large to calculate the factorial for
    elsif ($n > 100000) {
        print "Error: Input is too large to calculate the factorial for\n";
    }
    # Calculate the factorial of n
    else {
        # Using iterative approach
        my $factorial = Math::BigInt->new(1);
        for (my $i = 1; $i <= $n; $i++) {
            $factorial *= $i;
        }
        # Display the input and its factorial
        print "Iterative factorial of $input is $factorial\n";

        # Using recursive approach
        my $recursive_factorial = factorial($n);
        # Display the input and its factorial
        print "Recursive factorial of $input is $recursive_factorial\n";
    }
}
# Handle non-integer inputs
else {
    print "Error: Input must be a positive integer\n";
}

# Recursive function to calculate factorial
sub factorial {
    my $n = shift;

    # Base case
    return 1 if $n == 0;

    # Recursive case
    return $n * factorial($n - 1);
}
```

