import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.HashSet;

public class LiteraryWorksRepository {
    // A HashMap to store Author objects as keys and a set of their literary works stored in a HashSet as values
    private Map<Author, Set<Work>> repository;

    // Constructor
    public LiteraryWorksRepository() {
        this.repository = new HashMap<>();
    }

    // Add an author to the repository
    public void addAuthor(Author author) {
        if (!repository.containsKey(author)) {
            repository.put(author, new HashSet<>());
        }
    }

    // Remove an author and their works from the repository
    public void removeAuthor(Author author) {
        repository.remove(author);
    }

    // Add a literary work to the repository
    public void addWork(Author author, Work work) {
        if (repository.containsKey(author)) {
            repository.get(author).add(work);
        } else {
            // If the author does not exist in the repository, add them and their work
            Set<Work> works = new HashSet<>();
            works.add(work);
            repository.put(author, works);
        }
    }

    // Remove a literary work from the repository
    public void removeWork(Author author, Work work) {
        if (repository.containsKey(author)) {
            repository.get(author).remove(work);
        }
    }

    // Get the literary works associated with a particular author
    public Set<Work> getWorksByAuthor(Author author) {
        return repository.get(author);
    }

    // Inner class to represent an author
    public class Author {
        private String name;

        public Author(String name) {
            this.name = name;
        }

        public String getName() {
            return name;
        }

        public void setName(String name) {
            this.name = name;
        }

        @Override
        public boolean equals(Object obj) {
            if (obj == this) {
                return true;
            }

            if (!(obj instanceof Author)) {
                return false;
            }

            Author other = (Author) obj;
            return this.name.equals(other.name);
        }

        @Override
        public int hashCode() {
            return name.hashCode();
        }
    }

    // Inner class to represent a literary work
    public class Work {
        private String title;

        public Work(String title) {
            this.title = title;
        }

        public String getTitle() {
            return title;
        }

        public void setTitle(String title) {
            this.title = title;
        }

        @Override
        public boolean equals(Object obj) {
            if (obj == this) {
                return true;
            }

            if (!(obj instanceof Work)) {
                return false;
            }

            Work other = (Work) obj;
            return this.title.equals(other.title);
        }

        @Override
        public int hashCode() {
            return title.hashCode();
        }
    }
}

