```java
class CircularBuffer {
    private char[] buf;
    private int size;
    private int rightChars;

    public CircularBuffer(int size) {
        this.size = size;
        this.buf = new char[size];
        this.rightChars = 0;
    }

    public void write(char c) {
        buf[rightChars % size] = c;
        rightChars++;
    }

    public char read() {
        if (rightChars == 0) {
            throw new IllegalStateException("Buffer is empty");
        }
        char oldest = buf[(rightChars - size) % size];
        rightChars--;
        return oldest;
    }
}
```

