```java
import java.util.Arrays;
import java.util.List;
import java.util.ArrayList;
import java.util.function.Predicate;
import java.util.stream.IntStream;

public class Main {

    public static void main(String[] args) {
        print(pluck(Arrays.asList(4,2,3), x -> x % 2 == 0)); // Expected output: [2, 1, 6]
        print(pluck(Arrays.asList(5, 0, 3, 0, 4, 2), x -> x % 2 == 0)); // Expected output: [0, 1, 6]
        print(pluck(Arrays.asList(4,2,3), x -> x % 3 == 0)); // Expected output: [3, 2, 3]
        print(pluck(Arrays.asList(5, 0, 3, 0, 4, 2), x -> x % 3 == 0)); // Expected output: [0, 1, 3]
    }

    public static void print(List<Object> list) {
        System.out.println(list.toString());
    }

    public static List<Object> pluck(List<Integer> arr, Predicate<Integer> condFn) {
        int minVal = Integer.MAX_VALUE;
        int minIndex = 0;
        int totalSum = 0;
        for (int i = 0; i < arr.size(); i++) {
            int val = arr.get(i);
            if (condFn.test(val)) {
                totalSum += val;
                if (val < minVal) {
                    minVal = val;
                    minIndex = i;
                }
            }
        }
        if (minVal == Integer.MAX_VALUE) {
            // This means that no value fulfills the condition.
            return new ArrayList<>();
        } else {
            // Return the minimum value, its index and the total sum.
            return Arrays.asList(minVal, minIndex, totalSum);
        }
    }
}
```

