    func registerCompletionHandler(identifier: String, completionHandler: @escaping (Data) -> Void) {
        if completionHandlers[identifier] != nil {
            completionHandlers[identifier]?.append(completionHandler)
        } else {
            completionHandlers[identifier] = [completionHandler]
        }
    }

    func completeTask(identifier: String, fetchedData: Data) {
