You are tasked with implementing a simple chat server using Python's socket module. The server should be able to handle multiple clients connecting to it and exchanging messages with each other. Your task is to complete the implementation of the `ChatServer` class by filling in the missing methods.

```python
import socket
import threading

class ChatServer:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.clients = []
        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server_socket.bind((self.host, self.port))
        self.server_socket.listen(5)

    def broadcast(self, message, sender_socket):
        for client in self.clients:
            if client != sender_socket:
                try:
                    client.send(message.encode())
                except:
                    client.close()
                    if client in self.clients:
                        self.clients.remove(client)

    def handle_client(self, client_socket, client_address):
        while True:
            try:
                message = client_socket.recv(1024).decode()
                self.broadcast(message, client_socket)
            except:
                continue

    def start(self):
        while True:
            client_socket, client_address = self.server_socket.accept()
            self.clients.append(client_socket)
            client_handler = threading.Thread(target=self.handle_client, args=(client_socket, client_address))
            client_handler.start()

if __name__ == "__main__":
    server = ChatServer('127.0.0.1', 12345)
    server.start()
```

