function createNotebookCell(title, description, steps) {
  const SMALL_ICON_URL = "https://example.com/icon.png";
  const cells = [];

  const cellData = new vscode.NotebookCellData(
    1,
    `## ![Icon](${SMALL_ICON_URL})&nbsp;&nbsp; CodeTour (${title}) - ${steps.length} steps\n\n${description === undefined ? "" : description}`,
    "markdown"
  );

  cells.push(cellData);

  steps.forEach((step, index) => {
    const cell = new vscode.NotebookCellData(2, step.contents, step.language);
    cell.outputs = [
      new vscode.NotebookCellOutput([
        new vscode.NotebookCellOutputItem(
          step.language === "javascript" ? "text/plain" : "text/x-python",
          step.contents
        )
      ])
    ];
    cells.push(cell);
  });

  return {
    id: cells[0].id,
    data: cells[0].value,
    language: cells[0].language,
    outputs: cells.slice(1).map((cell) => ({
      outputItems: cell.outputs[0].items.map((item) => ({
        mime: item.mime,
        value: item.value
      }))
    }))
  };
}
```

