```cpp
#include<iostream>
using namespace std;

int calculateSum(int n) {
    int sum = 1; // 1 is a divisor of every number
    for (int i=2; i*i<=n; i++) {
        if (n%i == 0) {
            if (i == (n/i)) // if both divisors are same then add it only once else add both
                sum = sum + i;
            else
                sum = sum + (i + n/i);
        }
    }
    return sum;
}

int main() {
    int n;
    cout << "Enter a number: ";
    cin >> n;
    cout << "Sum of divisors: " << calculateSum(n);
    return 0;
}
