Here's how you can write above code in Rust:

```rust
use std::f32::consts::PI;

// In Rust, we use global constants like this
const RADIUS: f32 = 1.0;

// Translation of the triangle_area function in Rust
// Note that in Rust, function parameters are always explicitly typed 
// also there is no default arguments in Rust like in C++, so we create separate function for each type.
// Also Rust do not automatically round() function, so we use built-in methods of the f32 type.
// The function returns `Option<f32>` because it can fail; when it fails `None` is returned, in success case `Some(area)`
fn triangle_area_E(a: f32, b: f32, c: f32) -> Option<f32> {
    if a + b <= c || b + c <= a || c + a <= b {
        None
    } else {
        let s = (a + b + c) / 2.0;
        let area = (s * (s - a) * (s - b) * (s - c)).sqrt();
        Some((area * 100.0).round() / 100.0)
    }
}

fn triangle_area_S(a: f32, b: f32, c: f32) -> Option<f32> {
    if a + b + c > 360.0 {
        None
    } else {
        let a = a * PI / 180.0;
        let b = b * PI / 180.0;
        let c = c * PI / 180.0;
        let s = (a + b + c) / 2.0;
        let area = RADIUS * RADIUS * (s - a) * (s - b) * (s - c);
        Some((area * 100.0).round() / 100.0)
    }
}

// You can then use these functions like this:
fn main() {
    match triangle_area_E(3.0, 4.0, 5.0) {
        Some(area) => println!("The triangle area for type E is: {}", area),
        None => println!("There is an error in input for type E"),
    }

    match triangle_area_S(30.0, 60.0, 90.0) {
        Some(area) => println!("The triangle area for type S is: {}", area),
        None => println!("There is an error in input for type S"),
    }
}
```

