def isValid(s: str) -> bool:
    stack = []
    for i in s:
        if i == '(':
            stack.append(i)
        else:
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def parse_nested_parens_and_validate(s: str) -> list:
    groups = s.split()
    depths = []
    for group in groups:
        if not isValid(group):
            raise Exception('Invalid group of parentheses in input string: ' + group)
        depth = 0
        max_depth = 0
        for char in group:
            if char == '(':
                depth += 1
                if depth > max_depth:
                    max_depth = depth
            elif char == ')':
                depth -= 1
        depths.append(max_depth)
    return depths
