                    if word.lower() not in stop_words and not word.isdigit()]
    return [word for word in cleaned_data if len(word) > 1]


def get_stop_words(stop_words_file_path):
    if os.path.isfile(stop_words_file_path):
        with open(stop_words_file_path, 'r') as f:
            return [word.strip() for word in f.readlines()]
    else:
        return []


def remove_stop_words(data, stop_words):
    return [word for word in data if word not in stop_words]


