function bert_ner($csv_path, $apiUrl, $model_name = "dbmdz/bert-large-cased-finetuned-conll03-english") {
  $entities = [];
  if (($handle = fopen($csv_path, "r")) !== FALSE) {
    while (($data = fgetcsv($handle, 1000, ",")) !== FALSE) {
      // Assuming the text data is the 1st column of the csv file
      $text = $data[0];
      // HTTP context options (needed to set the http header and content)
      $opts = array(
          'http' => array(
            'method' => 'POST',
            'header' => 'Content-type: application/x-www-form-urlencoded',
            'content' => http_build_query(['text' => $text, 'model' => $model_name])
          )
      );
      // Create the context
      $context = stream_context_create($opts);
      // Execute the request with the created context
      $result = file_get_contents($apiUrl, false, $context);
      // Check if it returned any error
      if ($result === FALSE) {
        error_log("Error occurred while sending request");
        continue;
      }
      // Parse the JSON result to access the entities
      $result = json_decode($result, true);
