```java
public class CartesianPoint {
    public float x;
    public float y;

    // Constructor to initialize the point with given x and y coordinates
    public CartesianPoint(float x, float y) {
        this.x = x;
        this.y = y;
    }

    // Method to calculate the distance between two points
    public float distanceTo(CartesianPoint other) {
        float dx = this.x - other.x;
        float dy = this.y - other.y;
        return (float) Math.sqrt(dx * dx + dy * dy);
    }

    // Method to calculate the midpoint between two points
    public CartesianPoint midpointWith(CartesianPoint other) {
        float midX = (this.x + other.x) / 2;
        float midY = (this.y + other.y) / 2;
        return new CartesianPoint(midX, midY);
    }
}
```

```java
public class Main {
    public static void main(String[] args) {
        // Create two CartesianPoint objects
        CartesianPoint point1 = new CartesianPoint(3, 4);
        CartesianPoint point2 = new CartesianPoint(6, 8);

        // Calculate the distance between the two points
        float distance = point1.distanceTo(point2);
        System.out.println("Distance between point1 and point2: " + distance);

        // Calculate the midpoint between the two points
        CartesianPoint midpoint = point1.midpointWith(point2);
        System.out.println("Midpoint between point1 and point2: (" + midpoint.x + ", " + midpoint.y + ")");
