```php
// src/Command/DropDatabaseCommand.php

namespace App\Command;

use Doctrine\DBAL\Connection;
use Symfony\Component\Console\Command\Command;
use Symfony\Component\Console\Input\InputArgument;
use Symfony\Component\Console\Input\InputOption;
use Symfony\Component\Console\Input\InputInterface;
use Symfony\Component\Console\Output\OutputInterface;

class DropDatabaseCommand extends Command
{
    protected static $defaultName = 'app:database:drop';

    private $connection;

    public function __construct(Connection $connection)
    {
        $this->connection = $connection;
        parent::__construct();
    }

    protected function configure()
    {
        $this
            ->setDescription('Drop the database with the given name')
            ->addArgument('database_name', InputArgument::REQUIRED, 'The name of the database to drop')
            ->addOption('force', 'f', InputOption::VALUE_NONE, 'Force the operation without confirmation');
    }

    protected function execute(InputInterface $input, OutputInterface $output)
    {
        $databaseName = $input->getArgument('database_name');
        $force = $input->getOption('force');

        if ($force || $this->confirmAction($input, $output)) {
            $this->dropDatabase($databaseName);
            $output->writeln(sprintf('Database "%s" has been dropped successfully.', $databaseName));
        } else {
            $output->writeln('Operation aborted.');
        }

        return Command::SUCCESS;
    }

    private function confirmAction(InputInterface $input, OutputInterface $output): bool
    {
        if ($input->isInteractive()) {
            $confirmation = $this->getHelper('question')->ask($input, $output, 'Are you sure you want to drop the database? (y/n) ');
            return strtolower($confirmation) === 'y';
        }

        return false;
    }

    private function dropDatabase(string $databaseName): void
    {
        $params = $this->connection->getParams();
        $dbName = $params['dbname'];

        if ($dbName === $databaseName) {
            $this->connection->close();
        }

        $this->connection->getSchemaManager()->dropDatabase($databaseName);
    }
}
```
In this solution, we create a Symfony console command `DropDatabaseCommand` that accepts the database name as an argument and provides an option to force the database drop without confirmation. The `execute` method handles the execution of the command, checking for the force option and confirming the action if not forced. The `dropDatabase` method uses Doctrine's schema manager to drop the specified database.

