class DoublyLinkedList {
  constructor() {
    this.head = null;
    this.tail = null;
    this.length = 0;
  }

  deleteNodeAtPosition(position) {
    if (this.length === 0) {
      // Case 1: When the list is empty
      return;
    } else if (this.length === 1) {
      // Case 2: When there is only one node in the list
      this.head = null;
      this.tail = null;
      this.length = 0;
    } else {
      let current = this.head;
      for (let i = 0; i < position; i++) {
        current = current.getNext();
      }

      if (current === this.head) {
        // Case 3: Deleting the first node
        this.head = current.getNext();
        this.head.setPrev(null);
      } else if (current === this.tail) {
        // Case 4: Deleting the last node
        this.tail = current.getPrev();
        this.tail.setNext(null);
      } else {
        // Case 5: Deleting a node in between
        let prevNode = current.getPrev();
        let nextNode = current.getNext();
        prevNode.setNext(nextNode);
        nextNode.setPrev(prevNode);
      }
      this.length--;
    }
  }
}
