            Match match = Regex.Match(inputMessage, pattern);

            if (match.Success)
            {
                goalInformation["team"] = match.Groups["team"].Value.Trim();
                goalInformation["player"] = match.Groups["player"].Value.Trim();
                goalInformation["time"] = match.Groups["time"].Value;
            }

            return goalInformation;
        }
    }
}
