// Event handler for button click
private void Velha_Click(object sender, EventArgs e)
{
    Button clickedButton = (Button)sender;

    // Check if the clicked button is empty
    if (clickedButton.Text == "")
    {
        // Place the appropriate symbol on the button
        if (xTurn)
        {
            clickedButton.Text = "X";
            gameBoard[GetButtonRow(clickedButton), GetButtonColumn(clickedButton)] = 'X';
        }
        else
        {
            clickedButton.Text = "O";
            gameBoard[GetButtonRow(clickedButton), GetButtonColumn(clickedButton)] = 'O';
        }

        // Check for a winning condition or draw
        if (CheckForWin('X'))
        {
            MessageBox.Show("Player X wins!");
            ResetGame();
        }
        else if (CheckForWin('O'))
        {
            MessageBox.Show("Player O wins!");
            ResetGame();
        }
        else if (IsBoardFull())
        {
            MessageBox.Show("It's a draw!");
            ResetGame();
        }
        else
        {
            // Toggle the turn
            xTurn = !xTurn;
        }
    }
}

// Helper method to get the row index of the clicked button
private int GetButtonRow(Button button)
{
    if (button.Name.Contains("1")) return 0;
    else if (button.Name.Contains("2")) return 1;
    else return 2;
}

// Helper method to get the column index of the clicked button
private int GetButtonColumn(Button button)
{
    if (button.Name.Contains("1")) return 0;
    else if (button.Name.Contains("2")) return 1;
    else return 2;
}

// Helper method to check for a winning condition
private bool CheckForWin(char symbol)
{
    // Check rows, columns, and diagonals for the given symbol
    for (int i = 0; i < 3; i++)
    {
        if (gameBoard[i, 0] == symbol && gameBoard[i, 1] == symbol && gameBoard[i, 2] == symbol)
            return true; // Row win
        if (gameBoard[0, i] == symbol && gameBoard[1, i] == symbol && gameBoard[2, i] == symbol)
            return true; // Column win
    }
    if (gameBoard[0, 0] == symbol && gameBoard[1, 1] == symbol && gameBoard[2, 2] == symbol)
        return true; // Diagonal win
    if (gameBoard[0, 2] == symbol && gameBoard[1, 1] == symbol && gameBoard[2, 0] == symbol)
        return true; // Diagonal win

    return false; // No win
}

// Helper method to check if the board is full
private bool IsBoardFull()
{
    foreach (char cell in gameBoard)
    {
        if (cell == '\0') // Empty cell
            return false;
    }
    return true; // Board is full
}

// Helper method to reset the game
