{
    // Clear the game board array and reset the button texts
    gameBoard = new char[3, 3];
    foreach (Control control in this.Controls)
    {
        if (control is Button)
        {
            ((Button)control).Text = "";
        }
    }
    xTurn = true; // Reset the turn to 'X'
}
